'use strict';

/**
 * Main process entry / composition root. OWNER: lead.
 *
 * Wires the two main-process modules together. Workers do not edit this file;
 * each worker exposes the factory described in SPEC.md from its folder's
 * index.js and this file calls it.
 */

const path = require('node:path');
const { app, ipcMain } = require('electron');

require('dotenv').config({ path: path.join(__dirname, '..', '..', '.env'), quiet: true });

const { createCore } = require('./core'); // Worker 2
const { createShell } = require('./shell'); // Worker 1

// Global hotkeys and screen capture need X11. Mint Cinnamon is X11 by default;
// this keeps Electron off Wayland if a session ever runs one.
if (process.platform === 'linux') {
  app.commandLine.appendSwitch('ozone-platform', 'x11');
}

// One running instance only: a second launch just shows the existing panel.
if (!app.requestSingleInstanceLock()) {
  app.quit();
}

let shell = null;

app.whenReady().then(async () => {
  const dataDir = process.env.PROXY_DATA_DIR || app.getPath('userData');

  const core = await createCore({ dataDir, env: process.env });

  shell = await createShell({
    settings: core.settings,
    preloadPath: path.join(__dirname, '..', 'preload', 'preload.js'),
    rendererHtmlPath: path.join(__dirname, '..', 'renderer', 'index.html'),
  });

  core.registerIpc(ipcMain, { sendToPanel: shell.sendToPanel });
  shell.registerIpc(ipcMain);

  await shell.start();
});

app.on('second-instance', () => {
  if (shell) shell.showPanel();
});

app.on('will-quit', () => {
  if (shell) shell.dispose();
});

// Linux: quitting is explicit (tray/menu later); closing the panel quits for v0.
app.on('window-all-closed', () => app.quit());
